// Package inventory 判定低库存。这是一个评测 fixture，不是生产代码。
package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"runtime"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdsFile 是按仓库覆盖低库存阈值的配置文件，相对仓库根目录。
const thresholdsFile = "config/thresholds.json"

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 每次调用都重新读取 config/thresholds.json，所以运维改完文件立即生效，
// 不需要重新构建或重启。文件里没配的仓库回退到 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	path, ok := thresholdsPath()
	if !ok {
		return DefaultLowStockThreshold
	}
	return thresholdFrom(path, warehouse)
}

// thresholdFrom 返回 path 这份配置里 warehouse 的阈值，没配则回退默认值。
// 每次调用都重新读盘，保证文件改动立即生效。
func thresholdFrom(path, warehouse string) int {
	if value, ok := loadThresholds(path)[warehouse]; ok {
		return value
	}
	return DefaultLowStockThreshold
}

// loadThresholds 读取 path 里的按仓库阈值。文件缺失或格式非法时返回 nil，
// 调用方据此整体回退到默认值。
func loadThresholds(path string) map[string]int {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	thresholds := map[string]int{}
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil
	}
	return thresholds
}

// thresholdsPath 定位 config/thresholds.json：先从工作目录逐级往上找，
// 找不到再退回本包源码所在的仓库位置。第二种兜底是为了应对测试进程的
// 工作目录不是仓库根目录的情况。
func thresholdsPath() (string, bool) {
	if path, ok := findThresholdsUpward(); ok {
		return path, true
	}
	if _, file, _, ok := runtime.Caller(0); ok {
		path := filepath.Join(filepath.Dir(file), "..", thresholdsFile)
		if _, err := os.Stat(path); err == nil {
			return path, true
		}
	}
	return "", false
}

// findThresholdsUpward 从当前工作目录向上查找 config/thresholds.json。
func findThresholdsUpward() (string, bool) {
	dir, err := os.Getwd()
	if err != nil {
		return "", false
	}
	for {
		path := filepath.Join(dir, thresholdsFile)
		if _, err := os.Stat(path); err == nil {
			return path, true
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", false
		}
		dir = parent
	}
}

// IsLowStock 报告库存是否低于该仓库的阈值。
func IsLowStock(warehouse string, quantity int) bool {
	return quantity < LowStockThreshold(warehouse)
}

// LowStockWarehouses 返回 stock 里所有低库存的仓库，按名字排序。
func LowStockWarehouses(stock map[string]int) []string {
	low := make([]string, 0, len(stock))
	for warehouse, quantity := range stock {
		if IsLowStock(warehouse, quantity) {
			low = append(low, warehouse)
		}
	}
	sort.Strings(low)
	return low
}

package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

// config/thresholds.json 里配了哪些仓库，LowStockThreshold 就要返回哪些值。
func TestConfiguredWarehousesUseConfiguredThreshold(t *testing.T) {
	path, ok := thresholdsPath()
	if !ok {
		t.Fatal("找不到 config/thresholds.json")
	}
	configured := loadThresholds(path)
	if len(configured) == 0 {
		t.Fatal("config/thresholds.json 应当至少配置一个仓库")
	}
	for warehouse, want := range configured {
		if got := LowStockThreshold(warehouse); got != want {
			t.Errorf("LowStockThreshold(%q) = %d, 期望配置值 %d", warehouse, got, want)
		}
	}
}

// 改文件即可生效：同一个路径先后写两次、各读一次，第二次要反映新值，
// 中间不重新构建、不重启进程。
func TestThresholdChangeTakesEffectWithoutRebuild(t *testing.T) {
	path := filepath.Join(t.TempDir(), "thresholds.json")
	write := func(content string) {
		t.Helper()
		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
			t.Fatal(err)
		}
	}

	write(`{"beijing": 10}`)
	if got := thresholdFrom(path, "beijing"); got != 10 {
		t.Fatalf("thresholdFrom = %d, 期望 10", got)
	}

	write(`{"beijing": 20}`)
	if got := thresholdFrom(path, "beijing"); got != 20 {
		t.Fatalf("改配置后 thresholdFrom = %d, 期望 20", got)
	}
}

func TestUnconfiguredWarehouseUsesDefault(t *testing.T) {
	path := filepath.Join(t.TempDir(), "thresholds.json")
	if err := os.WriteFile(path, []byte(`{"beijing": 10}`), 0o644); err != nil {
		t.Fatal(err)
	}
	if got := thresholdFrom(path, "chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("未配置仓库 thresholdFrom = %d, 期望默认值 %d", got, DefaultLowStockThreshold)
	}
}

func TestMissingOrInvalidConfigUsesDefault(t *testing.T) {
	if got := thresholdFrom(filepath.Join(t.TempDir(), "missing.json"), "beijing"); got != DefaultLowStockThreshold {
		t.Fatalf("配置缺失应回退默认值，得到 %d", got)
	}

	path := filepath.Join(t.TempDir(), "invalid.json")
	if err := os.WriteFile(path, []byte(`not json`), 0o644); err != nil {
		t.Fatal(err)
	}
	if got := thresholdFrom(path, "beijing"); got != DefaultLowStockThreshold {
		t.Fatalf("配置非法应回退默认值，得到 %d", got)
	}
}

